constructor_data:
draw_each_time = draw_each_time_val;
/* Calculations */
RangeMode = RangeMode_val;              // Range mode
RangeMinutes = RangeMinutes_val;        // Range minutes
ModeStep =    ModeStep_val;             // Mode step (points)
HgPointScale = POINT_SCALE_100;        // Point scale
numberOfBars = numberOfBars_val;
VolumeType = VolumeType_val;            // Volume type
DataSource = DataSource_val;            // Data source

/* Histogram */
HgBarStyle = HgBarStyle_val;            // Bar style
HgPosition = HgPosition_val;            // Histogram position
HgColor =   HgColor_val;                // Color 1
HgColor2 =  HgColor2_val;               // Color 2
HgLineWidth = HgLineWidth_val;          // Line width

/* Levels */
ModeColor = ModeColor_val;              // Mode color
MaxColor =  MaxColor_val;               // Maximum color
MedianColor = MedianColor_val;          // Median color
VwapColor = VwapColor_val;              // VWAP color
ModeLineWidth = ModeLineWidth_val;      // Mode line width
StatLineStyle = StatLineStyle_val;      // Median & VWAP line style

ModeLevelColor = ModeLevelColor_val;    // Mode level line color (None=disable)
ModeLevelWidth = ModeLevelWidth_val;                     // Mode level line width
ModeLevelStyle = ModeLevelStyle_val;    // Mode level line style
RegionDividerColor = RegionDividerColor_val;   // Region divider lines color

/* Service */
Id_user =       Id_user_val;                      // Identifier
ShowHorizon = ShowHorizon_val;          // Show data horizon
Zoom =     0;                           // Zoom (0=auto)
WaitMilliseconds = 500;                 // Wait milliseconds
TimeFromColor = TimeFromColor_val;      // Left border line color
TimeFromStyle = TimeFromStyle_val;      // Left border line style
TimeToColor = TimeToColor_val;          // Right border line color
TimeToStyle = TimeToStyle_val;          // Right border line style
HgWidthPercent = HgWidthPercent_val;    // Histogram width, % of chart

/* miscellaneous */

shouldUpdate = true;

_modeStep =   0;

_prevBackgroundColor = clrNONE;


_firstVisibleBar = 0;
_lastVisibleBar = 0;


_isTimeframeEnabled = false;

_updateOnTick = true;




//Previously in OnInit

_prefix = Id + " m" + IntegerToString(RangeMode) + " ";
_tfn = Id + "-from";
_ttn = Id + "-to";
_hgPoint = _Point * HgPointScale;
_modeStep = ModeStep / HgPointScale;

_hgBarStyle = HgBarStyle;
_hgPointDigits = GetPointDigits(_hgPoint);

//Sajjad, save them here to fix color update issue in expert
_prevHgColor1 = _defaultHgColor1;
_prevHgColor2 = _defaultHgColor2;

_defaultHgColor1 = HgColor;
_defaultHgColor2 = HgColor2;

_hgLineWidth = HgLineWidth;

_modeColor = ModeColor;
_maxColor = MaxColor;
_medianColor = MedianColor;
_vwapColor = VwapColor;
_modeLineWidth = ModeLineWidth;

_statLineStyle = StatLineStyle;

_modeLevelColor = ModeLevelColor;
_modeLevelWidth = ModeLevelWidth;
_modeLevelStyle = ModeLevelStyle;

_showHg = !(ColorIsNone(_hgColor1) && ColorIsNone(_hgColor2));
_showModes = !ColorIsNone(_modeColor);
_showMax = !ColorIsNone(_maxColor);
_showMedian = !ColorIsNone(_medianColor);
_showVwap = !ColorIsNone(_vwapColor);
_showModeLevel = !ColorIsNone(_modeLevelColor);

_zoom = MathAbs(Zoom);

_dataPeriod = GetDataPeriod(DataSource);

/* Boundaries and multipliers */

timeFrom_str = timeFrom_str_val;
timeTo_str = timeTo_str_val;

how_many_regions = how_many_regions_val; //max is 5
region_1_factor = region_1_factor_val;
region_2_factor = region_2_factor_val;
region_3_factor = region_3_factor_val;
region_4_factor = region_4_factor_val;
region_5_factor = region_5_factor_val;
